-- Selecione previamente o banco criado no painel da hospedagem antes de importar.
-- Em hospedagem compartilhada, CREATE DATABASE e USE geralmente não são permitidos.
CREATE TABLE IF NOT EXISTS news(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(500) NOT NULL,description TEXT,content_excerpt MEDIUMTEXT,url TEXT NOT NULL,canonical_url VARCHAR(1000) NOT NULL,source_name VARCHAR(255),source_domain VARCHAR(255),published_at DATETIME,discovered_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,image_url TEXT,status VARCHAR(30) DEFAULT 'active',is_new TINYINT(1) DEFAULT 1,is_read TINYINT(1) DEFAULT 0,category VARCHAR(100),search_term VARCHAR(255),content_hash CHAR(64) NOT NULL,relevance_score TINYINT UNSIGNED DEFAULT 0,relevance_status ENUM('related','possibly_related','unrelated','manual_review') DEFAULT 'manual_review',relevance_reason TEXT,analysis_source ENUM('full_content','metadata') DEFAULT 'metadata',matched_entities JSON,manual_reviewed TINYINT(1) DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_hash(content_hash),KEY idx_canonical(canonical_url(191)),KEY idx_relevance(relevance_status,relevance_score),KEY idx_discovered(discovered_at));
CREATE TABLE IF NOT EXISTS sources(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,type VARCHAR(30) DEFAULT 'rss',url VARCHAR(1000) NOT NULL,active TINYINT(1) DEFAULT 1,last_checked_at DATETIME NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS search_terms(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,term VARCHAR(255) NOT NULL UNIQUE,weight INT DEFAULT 10,active TINYINT(1) DEFAULT 1,notes TEXT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS case_entities(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,normalized_name VARCHAR(255) NOT NULL,type VARCHAR(80) NOT NULL,relevance_weight INT DEFAULT 20,active TINYINT(1) DEFAULT 1,notes TEXT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_normalized(normalized_name));
CREATE TABLE IF NOT EXISTS monitor_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,source_id INT UNSIGNED NULL,search_term VARCHAR(255),status VARCHAR(30) NOT NULL,total_results INT DEFAULT 0,new_results INT DEFAULT 0,related_results INT DEFAULT 0,review_results INT DEFAULT 0,discarded_results INT DEFAULT 0,message TEXT,executed_at DATETIME DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_logs_source FOREIGN KEY(source_id) REFERENCES sources(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS settings(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,setting_key VARCHAR(100) NOT NULL UNIQUE,setting_value TEXT);
CREATE TABLE IF NOT EXISTS manual_reviews(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,news_id BIGINT UNSIGNED NOT NULL,previous_status VARCHAR(30),new_status VARCHAR(30) NOT NULL,notes TEXT,reviewed_at DATETIME DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_review_news FOREIGN KEY(news_id) REFERENCES news(id) ON DELETE CASCADE);
